  quizAttempts?: ModuleQuizAttempt[];
  practicalOutputs?: Record<string, boolean>;
};

export type AssessmentAttempt = StoredAssessmentAttempt;

export type WeakTopicReview = {
  topic: string;
  averageScore: number;
  dueDateIso: string;
  recommendedModuleId: string;
};

export type PdEntryType =
  | 'module-study'
  | 'quiz'
  | 'scenario'
  | 'flashcards'
  | 'practical-output'
  | 'focus-block'
  | 'reflection'
  | 'coaching';

